describe('File Upload - Size Limit Validation', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display error when file exceeds maximum size limit', () => {
    // Setup: intercept the file upload API
    cy.intercept('POST', '/api/files/upload').as('fileUpload');

    // Create a large file (e.g., 10MB)
    const largeFile = new File(['a'.repeat(10 * 1024 * 1024)], 'large-file.txt', {
      type: 'text/plain',
      lastModified: Date.now(),
    });

    // Attach the large file to the input
    cy.get('[data-testid="file-input"]').selectFile(largeFile);

    // Verify file name and size are displayed
    cy.get('[data-testid="file-name-display"]').should('contain', 'large-file.txt');
    cy.get('[data-testid="file-size-display"]').should('contain', '10MB');

    // Attempt to upload
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the API call
    cy.wait('@fileUpload');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'File size exceeds the maximum limit');

    // Verify upload was not successful
    cy.get('[data-testid="success-message"]').should('not.exist');
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');
  });

  it('should successfully upload file when within size limit', () => {
    // Setup: intercept the file upload API
    cy.intercept('POST', '/api/files/upload').as('fileUpload');

    // Create a small file (e.g., 1MB)
    const smallFile = new File(['a'.repeat(1 * 1024 * 1024)], 'small-file.txt', {
      type: 'text/plain',
      lastModified: Date.now(),
    });

    // Attach the small file to the input
    cy.get('[data-testid="file-input"]').selectFile(smallFile);

    // Verify file name and size are displayed
    cy.get('[data-testid="file-name-display"]').should('contain', 'small-file.txt');
    cy.get('[data-testid="file-size-display"]').should('contain', '1MB');

    // Attempt to upload
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the API call
    cy.wait('@fileUpload');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'File uploaded successfully');

    // Verify error message does not exist
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify file is removed from input after successful upload
    cy.get('[data-testid="file-input"]').should('have.value', '');
  });
});
